begin;
select no_plan();
select ok(not has_function_privilege('authenticated','api.execute_owner_profile_editor_server(uuid,text,jsonb)','EXECUTE'),'Browser cannot spoof gateway subject');
select ok(not has_function_privilege('anon','api.execute_owner_profile_editor_server(uuid,text,jsonb)','EXECUTE'),'Anonymous cannot call layout gateway');
select ok(has_function_privilege('service_role','api.execute_owner_profile_editor_server(uuid,text,jsonb)','EXECUTE'),'Server gateway available');
select ok(not has_function_privilege('service_role','api.save_current_owner_layout_working(jsonb)','EXECUTE'),'Original layout RPC remains private');
insert into auth.users(id,email) values('26200000-0000-4000-8000-000000000001','layout-gateway-one@example.test'),('26200000-0000-4000-8000-000000000002','layout-gateway-two@example.test');
create temporary table actors as select auth_user_id,owner_id from core.owner_auth_bindings where auth_user_id in('26200000-0000-4000-8000-000000000001','26200000-0000-4000-8000-000000000002');
update core.owner_onboarding_progress set current_step='preview_publish',primary_use_case='personal' where owner_id in(select owner_id from actors);
insert into core.owner_handle_namespaces(normalized_handle,owner_id,namespace_kind) select 'layout262-'||right(auth_user_id::text,6),owner_id,'current' from actors;
update core.owners set onboarding_completed_at=now() where id in(select owner_id from actors);
insert into core.identity_working(owner_id,display_name,bio,revision) select owner_id,'Source Profile','Retained Bio',2 from actors;
insert into core.identity_layout_working(owner_id,starter_key,revision) select owner_id,'clean',1 from actors;
insert into core.identity_publications(owner_id,snapshot,identity_revision,layout_revision,connection_revision,published_at) select owner_id,'{"legacy":true}',2,1,null,now() from actors;
set local request.jwt.claims='{"role":"service_role","sub":"26200000-0000-4000-8000-000000000002"}';
set local request.jwt.claim.sub='26200000-0000-4000-8000-000000000002';
set local role service_role;
select is(api.execute_owner_profile_editor_server('26200000-0000-4000-8000-000000000001','save_current_owner_layout_working','{"input_working":{"action":"save_layout_working","base_layout_revision":1,"starter_key":"social_focus"}}'),'{"status":"success","changed":true,"layout_working":{"starter_key":"social_focus","revision":2}}'::jsonb,'Selected service operation saves exact own layout');
select is(current_setting('request.jwt.claim.sub'),'26200000-0000-4000-8000-000000000002','Caller subject restored after layout dispatch');
select is(current_setting('request.jwt.claims')::jsonb,'{"role":"service_role","sub":"26200000-0000-4000-8000-000000000002"}'::jsonb,'Caller claims restored');
select is(api.execute_owner_profile_editor_server('26200000-0000-4000-8000-000000000001','save_current_owner_layout_working','{"input_working":{"action":"save_layout_working","base_layout_revision":2,"starter_key":"social_focus"}}'),'{"status":"success","changed":false,"layout_working":{"starter_key":"social_focus","revision":2}}'::jsonb,'Exact no-op preserves revision');
select is(api.execute_owner_profile_editor_server('26200000-0000-4000-8000-000000000001','save_current_owner_layout_working','{"input_working":{"action":"save_layout_working","base_layout_revision":1,"starter_key":"business"}}')->>'status','stale_write','Stale replay cannot overwrite');
select is(api.execute_owner_profile_editor_server('26200000-0000-4000-8000-000000000001','save_current_owner_layout_working','{"input_working":{"action":"save_layout_working","base_layout_revision":2,"starter_key":"featured","owner_id":"26200000-0000-4000-8000-000000000002"}}')->>'status','invalid_layout_working','Nested caller target denied');
select is(api.execute_owner_profile_editor_server('26200000-0000-4000-8000-000000000001','save_current_owner_layout_working','{"input_working":{},"owner_id":"26200000-0000-4000-8000-000000000002"}')->>'status','unavailable','Outer caller target denied');
select is(api.execute_owner_profile_editor_server('26200000-0000-4000-8000-000000000001','save_current_owner_layout_working','{}')->>'status','unavailable','Missing payload denied');
select is(api.execute_owner_profile_editor_server('26200000-0000-4000-8000-000000000001','publish_current_onboarding','{}')->>'status','unavailable','No publication dispatch');
reset role;
select is((select starter_key::text from core.identity_layout_working where owner_id=(select owner_id from actors where auth_user_id='26200000-0000-4000-8000-000000000002')),'clean','Foreign layout untouched');
select ok(not exists(select 1 from core.identity_publications where snapshot<>'{"legacy":true}'::jsonb),'Published snapshots unchanged');
select ok(not exists(select 1 from core.identity_working where owner_id in(select owner_id from actors) and (display_name<>'Source Profile' or revision<>2)),'Profile and its revision unchanged');
create function pg_temp.reject_layout_update() returns trigger language plpgsql as $$begin raise exception 'fixture layout write failure';end;$$;
create trigger layout_editor_fixture before update on core.identity_layout_working for each row execute function pg_temp.reject_layout_update();
set local role service_role;
select throws_ok($q$select api.execute_owner_profile_editor_server('26200000-0000-4000-8000-000000000001','save_current_owner_layout_working','{"input_working":{"action":"save_layout_working","base_layout_revision":2,"starter_key":"business"}}')$q$,'P0001','fixture layout write failure','Write exception propagates');
select is(current_setting('request.jwt.claim.sub'),'26200000-0000-4000-8000-000000000002','Exception restores caller subject');
reset role;
drop trigger layout_editor_fixture on core.identity_layout_working;
update core.owners set account_state='restricted' where id in(select owner_id from actors);
set local role service_role;
select is(api.execute_owner_profile_editor_server('26200000-0000-4000-8000-000000000001','save_current_owner_layout_working','{"input_working":{"action":"save_layout_working","base_layout_revision":2,"starter_key":"business"}}')->>'status','owner_not_eligible','Restriction prevents gateway write');
reset role;
select * from finish();
rollback;
